keyframes.css:
@keyframes sys-in { 
  0% { opacity: 0; transform: translate(-10px); }
  100% { opacity: 1; transform: none; }
}

@keyframes scan { 
  0% { opacity: 0; transform: translate(-32px); }
  6%, 18% { opacity: 1; transform: translate(-32px); }
  30%, 40% { transform: translate(-16px, -20px); }
  52%, 90% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: none; }
}

@keyframes stack { 
  0% { opacity: 0; transform: translateY(-10px); }
  10%, 80% { opacity: 1; transform: none; }
  90%, 100% { opacity: 0; transform: none; }
}

@keyframes b1 { 
  0% { opacity: 0; transform: none; }
  12%, 85% { opacity: 1; }
  100% { opacity: 0; transform: translate(48px, 12px); }
}

@keyframes b2 { 
  0% { opacity: 0; transform: none; }
  12%, 85% { opacity: 1; }
  100% { opacity: 0; transform: translate(48px, -4px); }
}

@keyframes b3 { 
  0% { opacity: 0; transform: none; }
  12%, 85% { opacity: 1; }
  100% { opacity: 0; transform: translate(48px, -20px); }
}

@keyframes wave { 
  0% { opacity: 0.9; transform: scale(1); }
  100% { opacity: 0; transform: scale(2.6); }
}

@keyframes snap { 
  0%, 10% { transform: translate(var(--sx),var(--sy)) rotate(var(--sr)); }
  24%, 86% { transform: none; }
  100% { transform: translate(var(--sx),var(--sy)) rotate(var(--sr)); }
}

@keyframes stamp { 
  0%, 40% { opacity: 0; transform: scale(0); }
  50%, 85% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0); }
}

@keyframes io-need { 
  0% { opacity: 0; transform: translateY(10px); }
  2%, 18.6% { opacity: 1; transform: none; }
  19.6%, 100% { opacity: 0; transform: translateY(-10px); }
}

@keyframes io-result { 
  0% { opacity: 0; transform: translateY(10px); }
  2%, 12.2% { opacity: 0.22; transform: none; }
  13.4%, 18.6% { opacity: 1; transform: none; }
  19.6%, 100% { opacity: 0; transform: translateY(-10px); }
}
